	@Test
	void closeClosesQueuedResultBeforeConsumption() throws Exception {
		CloseTrackingIteration queued = new CloseTrackingIteration();
		ProbeExecutor executor = new ProbeExecutor(queued, null);
		Thread worker = new Thread(executor::run, "join-executor-queued-result-test");
		worker.start();
		try {
			assertTrue(executor.published.await(5, TimeUnit.SECONDS), "result was not queued");
			executor.close();
			assertTrue(queued.closed.get(), "closing the executor must close an unconsumed queued result");
			assertEquals(1, queued.closeCount.get(), "the queued result has one owner after cancellation");
		} finally {
			executor.allowPublication();
			executor.close();
			worker.join(TimeUnit.SECONDS.toMillis(5));
			assertFalse(worker.isAlive(), "executor worker did not terminate");
		}
	}

	@Test
	void closeClosesResultPublishedAfterCancellation() throws Exception {
		CloseTrackingIteration late = new CloseTrackingIteration();
		ProbeExecutor executor = new ProbeExecutor(late, new CountDownLatch(1));
		Thread worker = new Thread(executor::run, "join-executor-late-result-test");
		worker.start();
		try {
			assertTrue(executor.started.await(5, TimeUnit.SECONDS), "executor did not start publishing");
			executor.close();
			executor.allowPublication();
			assertTrue(executor.published.await(5, TimeUnit.SECONDS), "late result was not published");
			assertTrue(late.closed.get(), "a result published after cancellation must be closed");
			assertEquals(1, late.closeCount.get(), "a late result must be closed exactly once");
		} finally {
			executor.allowPublication();
			executor.close();
			worker.join(TimeUnit.SECONDS.toMillis(5));
			assertFalse(worker.isAlive(), "executor worker did not terminate");
		}
	}

