		Thread publisher = new Thread(() -> executor.publishDirect(raced), "join-executor-blocked-publication-test");
		publisher.start();
		try {
			assertTrue(waitForState(publisher, Thread.State.TIMED_WAITING),
					"the publisher must be blocked by the full result queue before cancellation");
			executor.close();
			publisher.join(TimeUnit.SECONDS.toMillis(5));
			assertFalse(publisher.isAlive(), "blocked publisher did not observe executor cancellation");
			assertEquals(1, raced.closeCount.get(),
					"the close path and the cancelled publisher must claim the result exactly once");
		} finally {
			if (publisher.isAlive()) {
				publisher.interrupt();
			}
			executor.close();
			publisher.join(TimeUnit.SECONDS.toMillis(5));
		}
