	private static final class ProbeExecutor extends JoinExecutorBase<BindingSet> {
		private final CloseTrackingIteration result;
		private final CountDownLatch started = new CountDownLatch(1);
		private final CountDownLatch published = new CountDownLatch(1);
		private final CountDownLatch beforePublish;

		private ProbeExecutor(CloseTrackingIteration result, CountDownLatch beforePublish) {
			super(new EmptyIteration<>(), null, EmptyBindingSet.getInstance());
			this.result = result;
			this.beforePublish = beforePublish;
		}

		@Override
		protected void handleBindings() throws Exception {
			started.countDown();
			if (beforePublish != null) {
				beforePublish.await();
			}
			addResult(result);
			published.countDown();
		}

		private void allowPublication() {
			if (beforePublish != null) {
				beforePublish.countDown();
			}
		}

		private void publishDirect(CloseableIteration<BindingSet> iteration) {
			addResult(iteration);
		}
	}

	private static final class CloseTrackingIteration implements CloseableIteration<BindingSet> {
		private final AtomicBoolean closed = new AtomicBoolean();
		private final AtomicInteger closeCount = new AtomicInteger();
		private final RuntimeException closeFailure;

		private CloseTrackingIteration() {
			this(null);
		}

		private CloseTrackingIteration(RuntimeException closeFailure) {
			this.closeFailure = closeFailure;
		}

		@Override
		public boolean hasNext() {
			return false;
		}

		@Override
		public BindingSet next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			closeCount.incrementAndGet();
			closed.set(true);
			if (closeFailure != null) {
				throw closeFailure;
			}
		}
	}

	private static final class BlockingEmptyIteration implements CloseableIteration<BindingSet> {
		private final CountDownLatch hasNextEntered = new CountDownLatch(1);
		private final CountDownLatch allowHasNext = new CountDownLatch(1);
		private final AtomicInteger closeCount = new AtomicInteger();

		@Override
		public boolean hasNext() {
			hasNextEntered.countDown();
			try {
				allowHasNext.await();
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new QueryEvaluationException("interrupted while waiting for cancellation", e);
			}
			return false;
		}

		@Override
		public BindingSet next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			closeCount.incrementAndGet();
			allowHasNext.countDown();
		}
	}

	private static boolean waitForState(Thread thread, Thread.State expected) throws InterruptedException {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (System.nanoTime() < deadline) {
			if (thread.getState() == expected) {
				return true;
			}
			Thread.onSpinWait();
		}
		return thread.getState() == expected;
	}
